    code: "vector<int> leaders(const vector<int>& a) {\n    vector<int> out;\n    int greatestRight = INT_MIN;\n    for (int i = static_cast<int>(a.size()) - 1; i >= 0; --i) {\n        if (a[i] >= greatestRight) out.push_back(a[i]);\n        greatestRight = max(greatestRight, a[i]);\n    }\n    reverse(out.begin(), out.end());\n    return out;\n}",
